def praurut(simpul):
    hasil = [simpul]
    for anak in pohon[simpul]:
        hasil += praurut(anak)
    return hasil

def pascaurut(simpul):
    hasil = []
    for anak in pohon[simpul]:
        hasil += pascaurut(anak)
    return hasil + [simpul]

def tinggi(simpul):
    if not pohon[simpul]:
        return 0
    return 1 + max(tinggi(a) for a in pohon[simpul])

